/* ══════════════════════════════════════════════════════════════════
   Progress sync  ·  board items 4, 45, 46

   Before this module, user_progress / plan_progress / plan_enrollments existed in the
   database with zero references anywhere in the app. A signed-in member who reinstalled
   lost three years of reading and nothing about having an account brought it back.

   The merge rule matters more than the transport:

     completions are FACTS   -> union. Two devices offline at once may each hold days
                                the other never saw. A sync must never un-complete a day.
     preferences are CHOICES -> last write wins.

   Getting that backwards is how sync quietly deletes someone's work.
   ══════════════════════════════════════════════════════════════════ */

const SYNC_DIRTY_KEY = "flourish_sync_dirty";
const SYNC_STATE_KEYS = ["track","theme","startDate","xp","streak","lastActive","badges",
                         "quizzes","prayed","virtuesDone","gameWins","bestTrivia","onboarded","graceDay","__v"];
let _syncing = false;

function localDoneDays(){
  return Object.keys(S.done || {})
    .filter(k => k.indexOf("day") === 0)
    .map(k => parseInt(k.slice(3), 10))
    .filter(n => Number.isInteger(n) && n > 0 && n <= 1095);
}
