    const merged = [];
    for (const e of current) {
      const id = e.kind + "\u0000" + e.key;
      if (!(id in settled)) { merged.push(e); continue; }          // queued during the drain
      const replayed = batch.find(b => b.kind === e.kind && b.key === e.key);
      if (replayed && (e.seq || 0) > (replayed.seq || 0)) { merged.push(e); continue; }  // superseded
      if (settled[id]) merged.push(settled[id]);                   // failed: keep for retry
    }
