      const tell = _refusals[r.entry.kind];
      if (!tell || merged.some(e => e.kind === r.entry.kind && e.key === r.entry.key)) continue;
      try { tell(r.entry.args, r.message); }
      catch (x) { console.warn("[flourish] refusal handler failed", r.entry.kind, x); }
